# boxctl: timeout=120
R=$HOME/work/g9/runs; for j in g9-cohort-azure4 g9-cohort-ben64-azure4 g9-genx-stu-azure4; do n=$(ls $R/$j/run/receipts | wc -l); h=$(find $R/$j/run/receipts -name "*.json" -mmin -60 | wc -l); f=$(ls $R/$j/run/failures | wc -l); echo "$j $n last60=$h failures=$f"; done; df -h --output=avail $HOME | tail -1; iostat -dx 10 2 | grep nvme0n1 | tail -1 | awk "{print \"w/s\",\$8,\"w_await\",\$12,\"f/s\",\$(NF-3),\"util\",\$NF}"; vmstat 5 2 | tail -1
